    [F(1151,8684), F(1373,5289), F(580,5851), F(580,5851)],
    [F(259,5118), F(580,5851), F(1000,9999), F(139,8060)],
    [F(259,5118), F(580,5851), F(139,8060), F(1000,9999)],
]

def det(mat):
    n=len(mat)
    a=[row[:] for row in mat]
    sign=1
    d=Fraction(1,1)
    for i in range(n):
        piv=i
        for r in range(i,n):
            if a[r][i] "'!= 0:
                piv=r
                break
        if a[piv][i]==0:
            return Fraction(0,1)
        if piv!=i:
            a[i],a[piv]=a[piv],a[i]
            sign*=-1
        pivot=a[i][i]
        d*=pivot
        for r in range(i+1,n):
            if a[r][i]==0:
                continue
            factor=a[r][i]/pivot
            for c in range(i+1,n):
                a[r][c]-=factor*a[i][c]
            a[r][i]=Fraction(0,1)
    return Fraction(sign,1)*d

for k in range(1,5):
    print(f'"'lpd{k} = {det([row[:k] for row in M[:k]])}')

# LDL decomposition
n=4
L=[[Fraction(0,1) for _ in range(n)] for __ in range(n)]
D=[Fraction(0,1) for _ in range(n)]
for i in range(n):
    L[i][i]=Fraction(1,1)
for i in range(n):
    s = sum(L[i][k]*L[i][k]*D[k] for k in range(i))
    D[i] = M[i][i] - s
    for j in range(i+1,n):
        s = sum(L[j][k]*L[i][k]*D[k] for k in range(i))
        L[j][i] = (M[j][i]-s)/D[i]
print('D:')
for x in D:
    print(x)
print('L:')
for row in L:
    print(row)
# verify
for i in range(n):
    for j in range(n):
        val=sum(L[i][k]*D[k]*L[j][k] for k in range(n))
        if val"'!=M[i][j]:
            print('"'mismatch',i,j,val,M[i][j])
            raise SystemExit(1)
print('verified')
